      "answer": "1. 基本定律：动机强度与工作效率之间呈倒U型曲线关系，而非线性正比。在适度中等动机唤醒水平下，任务效率达到最高峰；动机过弱或过强都会导致效率显著下降。\n2. 任务难度与最佳唤醒水平的分化：\n• 简单、机械或熟练的日常任务：最佳动机水平偏高（较高的唤醒能激发能量，抵抗单调厌倦）。\n• 中等难度任务：最佳动机水平处于中等适度区间。\n• 复杂、高难度或高创造性认知任务：最佳动机水平偏低（保持相对平稳沉着的心理状态，避免思维视野局限）。\n3. 实践教育启示：在重大考试或复杂竞赛前，切忌对学生施加过度沉重的奖惩刺激，应协助其合理降温、调低心理预期以发挥最高思维水平；相反，在简单重复训练中，可适当引入竞争机制调动高积极性。",
