      "answer": "1. 内涵：自我效能感是个体对自己能否成功执行特定任务或应对挑战所具备的能力的主观信念与心理评价（区分于客观实际能力）。\n2. 自我效能感的四大信息来源（得分点）：\n① 个人自身行为的成败经验（最重要直接来源，成功提升效能，反复挫败降低效能）；\n② 替代性经验（观察与自身相似的榜样成功获得间接信心）；\n③ 言语劝说（来自权威、教师或同伴合情合理的鼓励引导）；\n④ 情绪唤醒与生理状态（紧张出汗心跳过速常被主观曲解为‘能力不足’）。\n3. 对行为的影响机制：\n• 决定任务选择：高效能者主动挑战高目标，低效能者回避挑战；\n• 决定努力程度与坚持性：遇到障碍时，高效能者更加坚韧付出倍增努力；\n• 影响认知思维与归因模式：高效能者归因于努力不足，低效能者自认能力缺陷导致习得性无助。",
