      "title": "简述注意的四种核心品质及其影响因素，并举例说明‘注意的分配’与‘注意的分散’的本质区别。",
      "options": [],
      "answer": "1. 注意的广度（范围）：在同一时间内能够清楚觉察到的客体数量（正常成人约为4-6个独立单元/组块）。受知觉对象的排列规律与知识经验影响。\n2. 注意的稳定性：注意在同一对象或活动上所能保持的时间持久程度。受对象丰富度、个人兴趣意志影响。注意在微观上存在周期性起伏（注意起伏）。\n3. 注意的分配：在同一时间内把心理注意合理指向两种或两种以上的不同活动（如边弹钢琴边看五线谱）。条件：必须至少有一项活动已达到自动化熟练程度。\n4. 注意的转移：根据新任务的要求，主动、自觉地把注意从一个对象转移到另一个对象（如上完数学课立刻切换至英语课）。\n5. 注意的分配 vs 注意的分散的区别（手写重点警示）：\n• 注意的分配是有预定目的的主动协调行为，能兼顾多任务且效率高；\n• 注意的分散（分心）是违背当前主观意志的不由自主的被动离开，会导致当前任务中断或严重失误。",
