      "title": "简述正强化、负强化、正惩罚与负惩罚的异同，并各举一例日常生活案例进行对比分析。",
      "options": [],
      "answer": "1. 共同维度与判别标准：\n• 目标维度：强化（无论正负）旨在【提高】行为发生率；惩罚（无论正负）旨在【降低】行为发生率。\n• 刺激操纵：正（Positive）代表【呈现/施加】刺激；负（Negative）代表【撤销/剥夺】刺激。\n2. 四大概念与实例对比：\n① 正强化：呈现愉快刺激以增加行为。例：孩子考了满分，父母奖励一台山地自行车，孩子后续学习更加刻苦。\n② 负强化：撤销厌恶刺激以增加行为。例：司机上车系好安全带后，车内刺耳恼人的蜂鸣报警声立刻消失，司机系安全带行为增加。\n③ 正惩罚：呈现厌恶刺激以减少行为。例：学生上课交头接耳，老师罚其抄写课文五遍或当众严厉批评，交头接耳行为减少。\n④ 负惩罚：撤销愉快刺激以减少行为。例：青少年沉迷网络旷课，父母切断家中WiFi并没收手机，旷课行为减少。",
