      "title": "简述班杜拉（Bandura）的社会学习理论，重点阐述观察学习的四个心理过程及强化的三种形式。",
      "options": [],
      "answer": "1. 观察学习的核心观点：班杜拉通过波波玩偶实验证实，人类的大多数行为并非仅仅通过直接试误和直接强化习得，而是通过在社会环境中观察榜样（Model）的行为及其产生的后果而进行的替代学习（Vicarious Learning）。\n2. 观察学习的四个心理子过程：\n① 注意过程（Attention）：注意并知觉榜样行为的显著特征；\n② 保持过程（Retention）：在头脑中以言语表象符号形式表征并储存所观察到的行为模式；\n③ 动作复现过程（Reproduction）：将头脑中的内部表象转化为外显动作，并对照反馈不断纠正精进；\n④ 动机过程（Motivation）：决定习得的行为是否付诸现实外显执行。受强化驱动。\n3. 班杜拉的三种强化形式（手写高频考点）：\n• 直接强化：观察者自己做出行为后亲身受到的外部直接奖惩；\n• 替代强化：观察者看到榜样做出某种行为受到奖惩，间接强化或抑制自身的行为（如看到别人因作弊被通报批评自己不再敢作弊）；\n• 自我强化：个体根据自己设立的内部崇高标准对自身行为进行自我奖励与赞许。",
      "explanation": "",
      "points": [
        "观察学习核心：替代学习机制，无需直接试误",
        "四个子过程：注意 ➔ 保持 ➔ 动作复现 ➔ 动机",
        "三种强化形式：直接强化、替代强化（榜样被奖惩的折射）、自我强化（内部标准奖赏）"
      ],
