      "title": "画出艾宾浩斯遗忘曲线的大致走势，详述遗忘的原因假说（衰退说、干扰说、压抑说、提取失败说），并结合心理学原理给出五条科学复习抗遗忘策略。",
      "options": [],
      "answer": "1. 艾宾浩斯遗忘曲线规律：遗忘在识记后立即发生，且进程呈现‘先快后慢、负加速’规律（最初20分钟遗忘超40%，随后逐渐平缓趋于稳定）。\n2. 遗忘四大理论假说：\n① 痕迹衰退说：记忆是脑神经建立的生理痕迹，未被强化复习则随时间自发衰退变淡。\n② 干扰抑制说：遗忘是由于前后学习材料之间的相互竞争抑制造成的（前摄抑制与倒摄抑制）。\n③ 动机性遗忘/压抑说（弗洛伊德）：个体因焦虑、内疚或痛苦，潜意识主动将创伤记忆压抑在意识之下。\n④ 提取失败说：长时记忆中的信息并未丢失，只是由于缺乏有效提取线索（如‘舌尖现象’TOT，只要提供恰当线索立即能回忆）。\n3. 科学复习策略：\n① 及时复习（根据先快后慢规律，学完立即巩固）；\n② 合理分配时间（分散复习效果显著优于考前突击集中复习）；\n③ 适当过度学习（过度学习达50%即150%时保持效率最高，超过200%造成厌恶疲劳）；\n④ 尝试回忆与反复识记相结合（主动自我测验效率远超被动重读）；\n⑤ 多种感觉通道协同并构建结构化思维导图（深加工与语义联结）。",
