      "options": [],
      "answer": "1. 影响问题解决的心理因素：\n① 问题表征方式：问题呈现空间越契合人脑直观图式，越容易突破；\n② 思维定势与功能固着：旧习惯套路和工具固定功能阻碍新思路萌发；\n③ 动机与情绪状态：耶克斯-多德森定律表明中等焦虑和适度动机最优，过度紧张导致思维狭窄；\n④ 原型启发与酝酿效应：相似物理原型的提示与潜意识后台孵化能促成顿悟；\n⑤ 已有专业知识结构：专家具备丰富的自动化组块模式识别能力。\n2. 创造性思维的三大核心品质（吉尔福特）：\n• 流畅性（Fluency）：在规定单位时间内产出思维观念和答案数量的多寡（思维速度快、点子多）；\n• 变通性/灵活性（Flexibility）：发散思维能够突破常规思维框架，灵活穿梭于不同知识领域（能举一反三，触类旁通）；\n• 独特性（Originality）：产生不同寻常、罕见、新奇且具有突破价值的独创方案（前无古人，独具匠心）。",
