      "answer": "1. 前习俗水平（9岁以下）：根据行为的外在直接物理后果与个人利害做判断。\n• 阶段1：惩罚与服从定向（为避免受罚而服从权威规则）；\n• 阶段2：相对功利取向（朴素利己主义，能满足自己需要的就算对，利尚往来）。\n2. 习俗水平（青少年及大多数成人）：根据社会主流规范、法律准则与他人赞许做判断。\n• 阶段3：寻求认可定向（‘好孩子’定向，以得到他人夸赞、符合人际期望为标准）；\n• 阶段4：维护社会秩序与权威定向（严格服从既定社会法律与制度，认为法律神圣不可侵犯）。\n3. 后习俗水平（少数成熟成人）：根据超越具体法规的普遍抽象道德哲学原则做判断。\n• 阶段5：社会契约与法律定向（认为法律是由社会契约制定的，若法律压迫人道应通过民主合法程序修正）；\n• 阶段6：普遍伦理道德原则定向（以良心为指南，认为人类生命尊严、人权自由与正义高于一切世俗法条）。",
