      "title": "【学姐手写“背”】简述格式塔心理学家考夫卡的行为环境论与勒温的生活空间理论，并对其进行客观评价（简答）",
      "options": [],
      "answer": "原笔记第20-21页手写【背】字核心大题：\n1. 考夫卡的行为环境论（《格式塔心理学原理》）：\n把环境分为【地理环境】和【行为环境】。前者指现实的环境，后者指个人意想中的环境。他认为行为产生于行为环境，受行为环境的调节。\n2. 勒温的动力场理论（《拓扑心理学原理》）：\n认为人是一个场，人的心理活动是在一种心理场或【生活空间】（Ls）里发生的。生活空间表示各种可能事件的全体，是在一定时刻决定个体行为的全部事实的总和，包括人与环境。\n公式：B = f(Ls) = f(P, E)。其中B代表个体行为，P代表个体的人，E代表心理环境（即与人的需求相结合在人脑中实际发生影响的环境，不是现实环境）。需求的作用使生活空间产生动力（引力或斥力），人的行为沿着引力方向向心理对象移动。生活空间的每一部分都有一个区域与疆界，人的行为就是在具有各个区域的生活空间中移动。\n3. 评价：\n• 合理性：考夫卡的行为环境论和勒温的生活空间论都把个体的心理因素注入到客观环境的作用过程中：①强调环境的作用取决于人的心理因素；②强调人对环境影响的行为反应的主动性；人在活动前对环境从主观上规定和把握，在认知心理学中称为“赋予意义”。环境对人们行为的影响是视个人对环境的认知而定的；\n• 局限性：他们片面强调个人心理因素的实在性及其作用，则有失偏颇。",
      "explanation": "",
