      "answer": "原笔记第4页红色手写必背要点：\n1. 描述心理事件：每一种心理事件都有质和量的特点。从质和量上进行描述，是心理学家进行系统实证研究的第一项任务，是心理学研究的最基本目的；\n2. 揭示心理规律：阐明心理现象在何时发生、如何发展以及怎样变化的内在必然联系；\n3. 探明心理机制：深入神经生理、脑机制和内部信息加工算法解释心理现象为什么会发生；\n4. 确定心理机能与调控：根据规律对未来的心理和行为进行科学预测，并对异常不良行为进行有效控制、矫正与引导。",
