      "title": "【高频对比】简述动物心理演变的三个主要阶段及其特征",
      "sourceTag": "【动物心理演变大题】",
      "answer": "1. 感觉阶段：代表动物为无脊椎动物（如草履虫、蚯蚓、昆虫）。神经形态：网状或节状神经。特征：只能反映客观事物的个别属性（如光线、温度、震动），无法综合完整物体形象。\n2. 知觉阶段：代表动物为脊椎动物（低等脊椎：鱼类、两栖、爬行；高等脊椎：鸟类、哺乳类）。神经形态：管状神经，形成脑泡与大脑皮层。特征：能够将事物的各种个别属性综合为一个整体客体映象进行反映。\n3. 思维萌芽阶段：代表动物为灵长类高级哺乳动物（如黑猩猩）。神经形态：大脑皮层高度褶皱发达。特征：不仅能反映事物整体，还能反映客观事物之间的外部空间与因果联系，借助工具解决简单直观动作问题，但尚无抽象概念与言语系统。",
