      "answer": "原笔记第19页简答必背要点：\n1. 家族史研究法：考察某种心理特征在血缘亲属中的发生率，亲缘关系越近，特征相似度越高，则遗传效应越大；\n2. 双生子研究法：比较同卵双生子（基因100%相同）与异卵双生子（基因50%相同）在特定心理行为上的相似程度，是分离遗传与环境效应的经典范式；\n3. 养子女研究法（寄养研究）：比较养子女与亲生父母（共享基因）以及养父母（共享环境）之间的特征相关性；\n4. 群体调查分析法：调查某种异常现象在一般群体中的出现率和患者亲属的出现率，测验其显著性。",
