      "title": "【五星大题】简述鲁利亚关于脑的三大机能系统的理论模型及其协同机制",
      "sourceTag": "【大题核心必背·每年必考】",
      "answer": "1. 第一机能系统（动力系统/调节系统）：由网状结构和边缘系统组成。功能：调节大脑皮层的觉醒水平和紧张度，为维持正常意识心理活动提供源源不断的基础心智能量。\n2. 第二机能系统（信息接收、加工和储存系统）：位于大脑皮层后部（枕叶视觉、颞叶听觉、顶叶躯体感觉）。功能：负责外界刺激的接受、综合分析和记忆编码。\n3. 第三机能系统（心理活动调节和控制系统）：位于大脑皮层前部（额叶及前额叶皮层）。功能：编制行为程序、组织并执行行动，对行动后果进行自我监控和反馈校正。\n4. 协同机制：任何复杂的心理与行为活动都不是单一系统孤立运作的产物，而是三大机能系统通力合作、联合协同的结果。",
