      "answer": "原笔记第24-26页真题要点：\n1. 社会影响含义：运用个人或团体的社会力量在特定方向上改变他人的观念和行为的过程。个人受他人影响的主要形式是从众与服从。\n2. 团体影响的三大表现：\n(1) 社会促进（社会助长）：个体完成某种活动时，由于他人在场或与他人一起活动而造成行为效率提高的现象（特里普利特自行车实验；受任务难度影响：提高简单任务成绩，降低复杂困难任务成绩）；\n(2) 社会懈怠（社会堕化/搭便车）：在团体中由于个体的成绩没有被单独加以评价，而是被视为一个总体时所产生的个体努力水平下降的现象（责任扩散、不可识别性）；\n(3) 去个性化（2017选、2019选）：个体把自己的情绪和行为融入群体情境，自我意识模糊、匿名性增加，做出平时不会做的反常越轨行为。",
