      "title": "【笔记标注（简答）】简述遗传与环境的交互作用的三种表现方式（简答）",
      "sourceTag": "【天性与教养争议简答】",
      "answer": "原笔记第27-28页简答要点：\n当代心理学家认为个体的身心发展是遗传与环境交互作用的结果。个体与环境的交互作用主要有三种表现方式：\n1. 反应的交互作用：面对相同的环境刺激，不同遗传基因的个体会以不同的方式对其作出反应。反应的交互作用贯穿毕生发展（例如：婴儿一出生就表现出气质上的先天倾向差异）；\n2. 唤起的交互作用：个体的遗传行为特征会招致周围人们对其产生不同的对待方式与反应（例如：父母的教养方式受到儿童自身性格特质的诱发与塑造）；\n3. 超前的交互作用：个体主动选择和创造自己所喜爱的环境，而这些环境反过来又进一步强化塑造个体（例如：攻击性很强的孩子主动选择与伙伴一起打架闹事，这一环境又反过来强化其攻击行为）。",
