      "answer": "原笔记第38页红色手写必背要点：\n意识并非只有一种水平，人们对信息的加工可以在不同的觉知水平上进行。不同的意识水平主要有五种：\n1. 焦点意识：人们集中注意而获得的清晰意识。任何时候，人们总是忽略一些刺激，选择一些刺激并屏蔽一些刺激；\n2. 下意识（与焦点意识相对应）【2019选】：未被注意的信息也是被登记和评估的，在觉知的下意识水平上起作用。边缘意识属于下意识（如鸡尾酒会现象）；\n3. 前意识【2017选】（承上启下）：人脑中许多当前不在意识之中的记忆和思维，在必要时可以把它带到意识中。如果想回忆的话就可以回忆起来，这时这些记忆便成为意识中清晰的组成部分；\n4. 潜意识：弗洛伊德创造的概念。某些痛苦记忆、冲动和欲望被压抑无法进入意识并继续影响人们的行为，是内省不能达到的心理现象（记忆和心理）；\n5. 非意识：身体内部由自主神经系统所支配的一些生理变化（如脑电活动、心跳、血压调节等生理活动），在正常情况下完全不被意识觉察。",
