      "answer": "原笔记第41页简答要点：\n1. 弗洛伊德精神分析愿望满足论：梦是潜意识中被压抑的冲动欲望在睡眠审查松懈时的伪装满足。包含做梦者醒后能回忆的【显梦】与隐藏在底层的【隐梦】（通过凝缩、移位、象征等加工伪装）；\n2. 霍布森神经生物学激活-整合理论（Activation-Synthesis）：REM期脑干脑桥随机自发电发放（激活），前脑大脑皮层试图将这些神经碎片信息综合编造为合理连贯的故事情节（整合）；\n3. 认知记忆巩固假说：梦是信息加工系统在对白天的记忆碎片进行筛选、分类与突触强化消除时的伴随心智体验。",
