      "answer": "原笔记第46页核心要点：\n1. 激活功能：动机具有发动行为的作用，能驱使机体从相对静止状态转向活动状态，表现为行为的发起与动员；\n2. 指向功能：动机具有使行为指向特定目标的作用，使个体的行为活动朝向符合个体需要的特定对象（如饥饿驱使个体去寻找食物而非水源）；\n3. 维持与调整功能：动机使个体的行为在克服阻碍的过程中持续坚持，并根据目标反馈适时调整行动方向与步调，直到达成预定目标。",
