      "category": "简答大题",
      "title": "【2017选/2024选】简述注意的三种主要类型及其产生条件与转化（简答）",
      "sourceTag": "【2017选/2024选·注意分类大题】",
      "answer": "原笔记第58-59页真题要点：\n1. 无意注意（不随意注意）：事先无预定目的，不需要意志努力。产生条件：刺激物的强烈物理强度、新异对比、运动突变，以及主观直接兴趣与身心疲劳度。\n2. 有意注意（随意注意）：有自觉目的，必须依靠意志努力克服困难。产生条件：清晰的间接兴趣与活动目的、对任务意义的深刻认识、智力活动组织、抗干扰意志力。\n3. 有意后注意（随意后注意）：事先有预定目的，但由于高度熟练已不再需要意志努力。产生条件：长期反复实践达到高度自动化熟练（如老司机开车、熟练织毛衣）。\n4. 相互转化：无意注意可转化为有意注意（被异常响声吸引后主动排查）；有意注意长期实践可转化为高级的有意后注意。",
