      "title": "【笔记标注（简答）】简述注意的四大品质（特征）及其影响因素（简答）",
      "sourceTag": "【注意四大品质简答】",
      "answer": "原笔记第60-61页简答要点：\n1. 注意的广度（范围）：同一时间能清楚觉察到的客体数目（成人约4-6个独立组块）。影响因素：客体排列规律性、知觉组织良好性、个人知识经验。\n2. 注意的稳定性：在同一对象或活动上所能保持的时间持久度。微观表现出周期性增强减弱的【注意起伏】。影响因素：刺激丰富度、主体意志投入、疲劳状态。\n3. 注意的分配：在同一时间内把注意合理指向两种或两种以上的不同活动。必备条件：必须至少有一项活动已达到自动化熟练程度；活动间已形成紧密神经联结。\n4. 注意的转移：根据新任务的要求，主动、自觉将注意从一个对象切换到另一个对象。影响因素：原活动的吸引与卷入程度、新活动的性质、个体的神经灵活性。",
