      "sourceTag": "【知觉四大特征大题必背】",
      "answer": "原笔记第74-76页真题要点：\n1. 知觉的选择性（对象性）：个体根据需要把某些对象从背景中区分出来优先加工（鲁宾双歧杯两可图）；\n2. 知觉的整体性：基于各个组成部分的空间关系将客观事物整合为一个有机完形（格式塔组织原则）；\n3. 知觉的理解性：利用已有知识经验去解释当前知觉对象并赋予意义（专业技师听发动机声辨故障）；\n4. 知觉的恒常性（2019选）：当知觉物理条件在一定范围内改变时，知觉映象保持相对稳定不变（大小、形状、明度、颜色恒常性）。\n相互关系：选择性确定对象，整体性构建完形，理解性赋予意义，恒常性保障物理世界表征的稳定性。",
