      "title": "【2025J真题】简述时间知觉与运动知觉的参考系及错觉产生的原因（简答）",
      "sourceTag": "【2025J真题·知觉参考系大题】",
      "answer": "原笔记第79-80页【2025J真题】要点：\n1. 时间知觉的参考系：自然界周期性节律（昼夜/四季）、有机体内部生理节律（心跳/生物钟/体温）、社会生活实践约定（作息表/钟表计时）。\n2. 运动知觉的参考系与错觉：运动知觉必须依赖参照系。当参照系选择错误时便产生运动错觉：\n• 诱发运动：周围大背景运动导致中间静止物体看似反向运动（夜空云飘看似月亮飞奔）；\n• 自主运动：暗室孤立微弱静止光点，由于眼肌微颤失去参照对比，看似飘忽游动；\n• 动景运动（似动现象/Phi现象）：两处静止刺激按特定时空交替闪烁，知觉为连续运动动画（霓虹灯/电影）。\n3. 错觉产生原因：感觉器官客观生理适应限制、知觉系统自动套用深度线索补偿导致的过调校正（大小-距离不变法则）、周围背景干扰产生的参照系混淆。",
