      "title": "【2018J真题】简述记忆的三级加工系统模型并举例说明其流程（简答）",
      "sourceTag": "【2018J真题·三级加工模型】",
      "answer": "原笔记第93页【2018J真题】要点：\n阿特金森与谢弗林提出记忆的三级加工信息系统模型：\n1. 感觉记忆（瞬时记忆）：刺激作用于感官形成的物理映象。容量巨大（9-12个），保持时间极短（图像记忆约0.25-1秒，声像记忆2-4秒）。例：眼前快速晃过的一串车牌号。\n2. 短时记忆（工作记忆）：经由注意筛选进入意识层的信息。保持时间约5秒-1分钟，容量为7±2个有意义组块（米勒规律）。例：查到电话号码后在拨号前心里默念几遍。\n3. 长时记忆：经由充分复述和深加工长久保持的信息。保持时间从几分钟到终生，容量无限，以语义编码和表象编码为主。例：熟记自己的高考成绩、乘法口诀表。",
