      "answer": "原笔记第108-109页【2025L真题】要点：\n1. 华莱士（Wallas）创造性思维四阶段：\n① 准备期（搜集资料，明确问题，深思熟虑）；\n② 酝酿期（潜意识静默孵化重组，暂时搁置问题，酝酿效应）；\n③ 顿悟期（灵感突发，豁然开朗，阿基米德浮力灵感）；\n④ 验证期（严谨检验论证逻辑方案的科学性与实用性）。\n2. 创造者的思维核心特点（吉尔福特）：\n• 发散思维为核心：具备【流畅性】（思维速度敏捷，点子极多）、【变通性/灵活性】（突破分类框架，跨界融会贯通）、【独特性】（新奇非凡，敢于提出前所未有的突破方案）；\n• 敏锐的问题发现意识与好奇心；\n• 善于运用远距离联想与非逻辑直觉直观。",
