      "sourceTag": "【知觉错觉机制简答】",
      "answer": "原笔记第80-81页简答要点：\n1. 错觉的概念：在特定客观条件下必然产生的、对客观事物歪曲的知觉映象。错觉是客观存在的生理心理现象，只要诱发条件存在，主观经验无法彻底消除错觉。\n2. 常见错觉分类：\n• 几何错觉：缪勒-莱尔错觉（箭形错觉）、潘佐错觉（铁轨透视错觉）、艾宾浩斯错觉（周围大圆衬托小中心圆）、佐尔拉错觉（平行斜线交错）；\n• 运动错觉：动景运动（似动现象）、自主运动（暗室孤立光点漂移）、诱发运动（云动月行）；\n• 形重错觉、视听错觉等。\n3. 错觉产生的原因（机制）：\n① 生理原因：感觉器官在物理结构和神经传导上的局限性与生理相互作用（如侧抑制网络与眼肌微颤）；\n② 认知心理原因：大脑深度线索知觉恒常性的过度补偿校正（大小-距离不变法则在平面的错误套用）；\n③ 环境参照系错误：知觉系统选择错误的物理参照背景作为基准。",
