      "answer": "原笔记第87-88页【2018选真题】要点：\n1. 学习迁移的概念：一种学习对另一种学习产生的影响，包括知识、技能和学习态度的跨情境应用。\n2. 迁移的种类：\n• 正迁移（促进） vs 负迁移（干扰，如英语音标干扰汉语拼音）；\n• 顺向迁移（前对后影响） vs 逆向迁移（后对前影响）；\n• 水平迁移（横向/同难度） vs 垂直迁移（纵向/自下而上概括提升）；\n• 具体迁移（要素相同） vs 一般迁移（普遍原理态度）。\n3. 经典迁移理论：\n① 形式训练说（沃尔夫）：官能心理学，认为心智官能（记忆力、意志力）如肌肉般经过拉拉丁文和几何训练即可通用提升；\n② 相同要素说（桑代克）：只有两种学习情境之间存在客观相同的物理或心理反应要素时，迁移才会发生；\n③ 概括化理论（贾德水下击靶实验）：迁移的关键不在于相同要素，而在于学习者对两种任务共同原理法则的理解与概括程度；\n④ 关系转换说（格式塔苛勒小鸡啄米实验）：迁移是个体对两情境中手段与目的整体关系的完形顿悟洞察。",
