      "answer": "原笔记第104-106页【2026选真题】要点：\n1. 概念界定：演绎推理是由一般原理推导出特殊结论的过程（三段论）；归纳推理是由具体事实概括出一般法则的过程。\n2. 影响演绎推理的心理因素（2026选）：\n① 气氛效应（Woodworth）：三段论前提的性质（全称/特称、肯定/否定）产生某种气氛，诱导被试得出具有相同性质的形式结论；\n② 信念偏差效应：当结论符合个体已有常识信念时，即使推理逻辑荒谬，被试也极易判定推理有效；\n③ 认知负荷与工作记忆限制：推理涉及多个心智模型表征时，工作记忆超载导致推理崩塌。\n3. 影响归纳推理与决策的启发式偏差（卡尼曼）：\n• 代表性启发式：仅凭与典型原型的相似度做概率推断（忽视基础比率谬误）；\n• 可得性启发式：凭脑海中容易被回忆提取的生动案例推估事件发生率；\n• 证实偏差（Confirmation bias）：个体强烈倾向于搜寻支持自身已有假设的证据，漠视甚至排斥反面证据。",
