      "answer": "原笔记第117页手写口诀【情话寄语】核心大题：\n言语产生受多种内在与外部心理因素的综合制约：\n1. 情绪状态（‘情’）：情绪唤醒与焦虑程度直接影响言语流畅度。适度焦虑促进精细选词，过度焦虑恐慌导致发音结巴、语塞卡壳、语法结构破碎；\n2. 说话动机与交际意图（‘话’）：说话者当下的交际意图、对听众背景的预估及社会目标决定了词汇句法风格的选择；\n3. 记忆与心智资源（‘寄’/记）：工作记忆容量和长时记忆词库检索提取速度直接限制了复杂嵌套长句的口语规划构建；\n4. 语言环境与上下文语境（‘语’）：交际的社会物理情境、人际关系地位、上下文对话脉络制约着语用选择与表达风格。",
