      "title": "【2024J/2026选】简述心理测验的信度、效度及其关系（简答）",
      "sourceTag": "【2024J/2026选·心理测量经典大题】",
      "answer": "原笔记第138-140页【2024J】【2026选】要点：\n1. 信度（Reliability）：指同一个测验对同一批被试施测所得结果的跨时间、跨评分者的一致性与稳定性程度。常见类型：重测信度、复本信度、分半信度、同质性信度（克伦巴赫α系数）、评分者信度。\n2. 效度（Validity）：指一个测验能够真正测量出其所欲测量的心理特质或行为特性的准确程度。常见类型：内容效度、构想效度（结构效度）、效标关联效度（同时效度与预测效度）。\n3. 信度与效度的辩证关系：\n• 信度是效度的必要条件，但不是充分条件（高信度不保证高效度；而高效度必然具备高信度）；\n• 一个测验若缺乏一致稳定性（信度低），其准确性（效度）必然极低；\n• 一个测验可以信度极高但完全无效（例如用极其精准的秤去测量人的智商，每次称重数据高度一致信度为1，但对智力测量效度为0）。",
      "points": [
        "信度：测量结果的一致性、稳定性和可靠性（重测/复本/分半/同质性信度）（2024J）",
        "效度：真正测出所欲测量特质的真实准确程度（内容/构想/效标效度）（2026选）",
        "信度与效度关系：信度是效度必要非充分条件；信度低则效度必低；信度高效度不一定高；高效度必具备高信度"
      ]
