      "answer": "原笔记第150-151页简答要点：\n1. 荣格（Jung）的人格结构论（分析心理学）：\n• 意识与自我：处于表层，是意识觉知的中枢；\n• 个体潜意识：受压抑的个人遗忘经验，核心表现为各种‘情结’（Complex）；\n• 集体潜意识：最深层核心建构，是人类世代祖先共同遗传沉淀下来的原始经验原型（Archetype），如人格面具（Persona）、阿尼玛（男性内心的女性原型）、阿尼姆斯（女性内心的男性原型）、阴影（Shadow）及自性（Self）。\n2. 弗洛姆（Fromm）的人格类型理论（社会性格论）：\n• 核心主张：人格是先天生物潜能与后天社会经济文化条件交互作用的产物；\n• 非生产性取向（不健康适应）：接受取向（依赖顺从他人）、剥削取向（巧取豪夺欺诈他人）、贮藏取向（固守吝啬自我封闭）、市场取向（视自我为商品随行就市换取利益）；\n• 生产性取向（健康成熟健全人格）：通过自主创造性劳动、理性思考与真诚的爱来实现自我潜能。",
