      "title": "【2023L真题】简述人格评鉴中自陈量表与投射测验的原理与优缺点对比（简答/论述）",
      "sourceTag": "【2023L真题·人格评鉴大题】",
      "answer": "原笔记第155-156页【2023L真题】要点：\n1. 自陈量表（客观测验，如MMPI、16PF、大五NEO-PI）：\n• 原理：特质论范式。采用结构明确陈述题，由被试按自身实际情况如实自我报告。\n• 优点：题目标准化，计分客观快速，信度效度系数通常较高，便于大样本团体施测；\n• 缺点：表面效度透明，被试极易产生‘社会赞许性掩饰’（挑体面好听的选）或装病，且只能测查被试意识觉知到的特质。\n2. 投射测验（主观测验，如罗夏墨迹测验、主题统觉测验TAT）：\n• 原理：精神分析投射机制。提供模糊无结构的刺激材料，让被试在没有标准答案的情境下自由联想编造故事，将深层潜意识冲动、压抑冲突与隐藏动机投射出来。\n• 优点：刺激歧义模糊，被试很难揣摩测验真实意图无法刻意伪装，能够穿透意识防御深挖潜意识人格动力；\n• 缺点：施测对主试专业临床素养要求极高；计分和解释带有强烈主观经验色彩，重测信度与实证效度长期受测量学质疑，标准化成本巨大。",
