      "title": "【笔记标注（简答）】简述意志行动的两个阶段及其工作机制（简答）",
      "sourceTag": "【意志行动过程大题】",
      "answer": "原笔记第131页简答要点：\n意志行动是人类自觉确立目的并克服困难实现目的的过程，通常由两个紧密相连的阶段组成：\n1. 采取决定阶段（准备阶段）：\n• 发生动机冲突斗争：在多种互相对立的愿望与冲动之间进行权衡取舍（解决双趋、双避、趋避冲突）；\n• 确立行动目的：明确要达到的终极目标及其社会价值；\n• 制定具体实施计划与策略：论证达到目的的各种可能途径与操作步骤，预见可能遭遇的困难险阻。\n2. 执行决定阶段（意志行动最关键的核心阶段！）：\n• 意义：将主观内隐的计划付诸客观现实行动的攻坚关口，意志品质的强弱最直接体现在执行阶段；\n• 核心机制：个体必须动员全部身心能量，长期坚忍地克服外部客观环境的困难（恶劣条件、诱惑干扰）和内部主观心理的阻碍（身体疲劳、动摇懈怠、消极情绪）；\n• 调控反馈：根据行动进展的现实后果反馈，适时调整策略，不达目的誓不罢休。",
