      "title": "【2018J真题】简述斯皮尔曼二因素说与瑟斯顿群因素说的分歧与理论整合（简答）",
      "sourceTag": "【2018J真题·智力经典理论大题】",
      "answer": "原笔记第140-141页【2018J真题】要点：\n1. 斯皮尔曼（Spearman）二因素理论：\n• 核心主张：人类能力由一般因素（G因素）和特殊因素（S因素）组成；\n• G因素（General Factor）：存在于一切智力活动中的普遍心智能量，是完成一切认知任务的共同心理基础，在各项智力测验中起主导决定作用；\n• S因素（Specific Factor）：只在特定作业任务中发挥作用的特殊能力；\n• 观点：智商测验测量的核心就是个体拥有的G因素多寡。\n2. 瑟斯顿（Thurstone）群因素理论（多因素说）：\n• 核心分歧：坚决反对单一统治性的G因素，认为智力是由若干种相对独立的彼此平行的基本心理能力构成的；\n• 七种基本心理能力（PMA）：计算能力、言语理解、词汇流畅性、空间知觉、机械记忆、知觉速度、归纳推理能力。\n3. 现代理论整合（层次结构模型）：\n• 现代心理测量学（如卡罗尔CHC模型、弗农层次群因素说）将二者辩证统一：底层为大量具体特殊技能（S），中层为若干相对独立的大因素群（瑟斯顿基本能力），顶层统摄着最高阶的一般心智能量（斯皮尔曼G因素）。",
      "points": [
        "斯皮尔曼二因素论：普遍心智G因素（决定性基础） ＋ 特殊任务S因素",
        "瑟斯顿群因素论：反对单一G因素，提出计算/言语/空间等7种基本心理能力（PMA）（2018J）",
        "现代层次结构整合：顶层统摄G因素，中层为群因素，底层为具体特殊能力"
      ]
