      "answer": "原笔记第152页简答要点：\n人本主义心理学家坚决反对行为主义的机械外在强化论与精神分析的病理潜意识宿命论，强调健康积极的人性潜能：\n1. 马斯洛的自我实现人格论：\n• 核心主张：人具有先天固有的成长趋势和崇高潜能，自我实现是人类最高动机追求；\n• 自我实现者的人格特征：对现实具有敏锐深刻的洞察力；全面悦纳自我与他人；保持自发纯真与独立自主；具有深厚的人类博爱同理心；富有创造性；常常体验到忘我的【高峰体验】（Peak experience）。\n2. 罗杰斯的自我理论（以人为中心人格论）：\n• 核心建构：自我概念（Self-concept），包含【真实自我】与【理想自我】；\n• 心理适应与心理健康：当真实自我与理想自我高度重叠一致时，个体心理健康和谐；当真实自我与理想自我严重脱节冲突时，产生强烈焦虑、防御机制与病理心理；\n• 人格健康成长条件：个体必须在早期成长中获得重要的社会抚养者给予的【无条件积极关注】（Unconditional positive regard），从而能接纳真实的自己，成为一个‘充分发挥机能的人’（Fully functioning person）。",
