      "answer": "原笔记第153-154页简答要点：\n特质论认为特质是构成人格的基本单位，是跨情境引导个体行为倾向的相对持久稳定的心理结构：\n1. 奥尔波特（Allport）人格特质理论：\n• 共同特质：同一文化形态下人们共同拥有的特质；\n• 个人特质：个体身上独一无二的特质，分为三个层级：\n  ① 首要特质（Cardinal traits）：统治支配一个人全部生活的极端罕见特质（如林黛玉的多愁善感、葛朗台的贪婪吝啬）；\n  ② 核心特质（Central traits）：每个人通常拥有5-10个的核心特征，最能代表其行为风格（如真诚、果断、勤奋）；\n  ③ 次要特质（Secondary traits）：仅在特定狭窄情境下表现出的微弱特殊偏好（如喜爱某种特殊衣着食物）。\n2. 卡特尔（Cattell）16PF因素分析特质论：\n• 表面特质（Surface traits）：从外部可以直接观察到的一群相互关联的行为表现；\n• 根源特质（Source traits）：深藏于人格深处、决定表面特质本质的独立维度；\n• 卡特尔通过因素分析法从词库中最终提炼出16种相互独立的根源特质，并编制了著名的【16种人格因素测验】（16PF）。",
