      "answer": "原笔记第16-17页简答要点：\n1. 额叶（Frontal Lobe）：位于大脑前半部（中央沟之前）。包含初级运动皮层与前额叶联合区。核心功能：负责动作控制与执行、高级认知规划决策、情绪调节、创造性思维及言语运动表达（左半球布罗卡区）；\n2. 顶叶（Parietal Lobe）：位于中央沟之后、枕叶之上。包含初级躯体感觉皮层（中央后回）。核心功能：处理触觉、温觉、冷觉、痛觉、本体感觉以及空间注意与身体表征定位；\n3. 枕叶（Occipital Lobe）：位于大脑后下部。包含初级视觉皮层与次级视觉联合区（距状裂周围）。核心功能：处理视网膜传入的光信号，整合视觉特征（形状、颜色、运动、空间关系）；\n4. 颞叶（Temporal Lobe）：位于外侧裂下方。包含初级听觉皮层（颞横回）与记忆情绪回路（海马、杏仁核相邻）。核心功能：负责听觉加工、言语理解（左半球韦尼克区）与复杂物体识别及长时记忆整合。",
