      "answer": "原笔记第18页要点：\n斯佩里切断癫痫患者连接左右半球的胼胝体，使两半球信息无法直接交叉交换，进行了经典的割裂脑实验：\n1. 实验过程：利用速示器向患者左视野或右视野短暂呈现物体图片（呈现时间短于眼动时间，约0.1秒）。\n• 向右视野呈现图片：光信号投射至左半球（语言优势半球），患者能立刻清楚、大声地说出看到的物体名称，并能用右手写出或拿起该物体；\n• 向左视野呈现图片：光信号投射至右半球（非语言半球）。右半球控制左手动作但缺乏言语表达能力，由于胼胝体被切断，右半球无法将信息传递给左半球语言中枢。结果表现为：患者‘哑口无言’，宣称自己什么也没看到；但其实验却能用左手从布袋中准确摸出该物体！\n2. 理论结论：证实了大脑两半球功能的单侧化（功能不对称性）。左半球主管言语、逻辑分析、抽象数学推理；右半球主管空间知觉、面孔识别、音乐艺术感知与情绪直觉整合。",
