      "id": "rec_9_64",
      "chapterId": 9,
      "category": "简答大题",
      "title": "【生理机制】简述从亮处进入暗室时的“暗适应”全过程及其光化学与感受器生理机制",
      "sourceTag": "【大题核心必背·生理机制详述】",
      "answer": "原笔记第66-67页简答要点：\n1. 暗适应全过程：指人从明亮强光环境突然进入黑暗室内时，视觉感受性由弱到强、逐渐恢复提升的完整适应过程。历时约30-40分钟。\n2. 双阶段特征与折点：\n• 第一阶段（前5-8分钟）：中央凹‘视锥细胞’主导，适应速度快但灵敏度极限较低；\n• 第二阶段（拐点之后）：视网膜周边‘视杆细胞’主导，感受性出现跨数量级飞跃提升持续至30-40分钟达到顶峰。\n3. 光化学机制：\n• 视杆细胞内的感光物质为‘视紫红质’。在白昼强光下视紫红质几乎被彻底分解漂白；\n• 进暗处后，视蛋白与视黄醛重新复合成视紫红质，浓度累积使微光捕获能力暴增数万倍。\n4. 补充考点：普肯耶现象（Purkinje phenomenon）——暗适应过程中光谱敏感度峰值从红黄色区（555nm）向蓝绿色区（505nm）偏移。",
