      "sourceTag": "【操作条件作用原理运用简答】",
      "answer": "原笔记第86-87页简答要点：\n斯金纳操作条件作用原理被广泛应用于教育教学与临床行为矫正：\n1. 行为塑造（Shaping，连续接近法）：\n• 通过对朝向最终目标行为的每一次微小的连续接近反应予以即时强化，从而使有机体逐步建立起原本不会自发产生的复杂新行为模式（如驯兽表演、孤独症儿童语言训练）；\n2. 代币制（Token Economy）：\n• 运用具有交换价值的次级强化物（如积分、小红花、代币筹码）对目标良好行为进行即时强化，积攒到一定数量后可兑换实质性的初级消费强化物（看电影、奖品玩具）；\n3. 普雷马克原理（祖母原则）：\n• 用高频发生的优势喜爱行为（如打游戏）作为强化物，去强化低频发生的劣势目标行为（如做作业、背单词）；\n4. 消退与惩罚的审慎使用：\n• 对不良行为采取‘消退’（彻底撤除导致不良行为维持的注意与关注），减少使用暴力体罚。",
