      "sourceTag": "【四大经典情绪理论流变大题】",
      "answer": "原笔记第126-127页【2018选真题】核心大题：\n1. 詹姆斯-兰格理论（外周自主神经论）：\n• 外部刺激 ➔ 机体内脏与外周生理变化 ➔ 产生主观情绪体验（“因为哭泣所以悲伤，因为奔跑所以害怕”）。情绪是对身体生理变化的知觉反馈。\n2. 坎农-巴德理论（丘脑中枢论）：\n• 外部刺激 ➔ 丘脑中转 ──┬──▶ 大脑皮层（产生主观情绪体验）\n                          └──▶ 自主神经系统（产生生理唤醒）── 两者由丘脑双向发射、并行发生无因果。\n3. 沙赫特-辛格双因素理论（认知生理评价论）：\n• 情绪是生理唤醒（提供能量）与环境认知评价（定性解释）的双重乘积。肾上腺素注射实验证实：当体内发生无法解释的高唤醒时，大脑会主动搜寻外部环境线索进行归因，决定最终的情绪性质。\n4. 阿诺德“评定-兴奋说”：\n• 刺激 ➔ 感觉中枢 ➔ 大脑皮层进行【利害评价（危险/有益）】 ➔ 神经冲动下行至下丘脑 ➔ 激发具体情绪与面部肌肉表情。",
