      "sourceTag": "【格罗斯情绪调节模型简答】",
      "answer": "原笔记第127-128页简答要点：\n格罗斯认为情绪调节是一个在情绪产生发展的各个时间点上动态展开的多阶段过程，包括两大阶段五大核心策略：\n1. 先行关注的情绪调节（情绪充分爆发之前发生）：\n① 情境选择：个体主动选择接近或回避特定的人事物，以调控情绪发生的可能性（如害怕吵架而主动避开某些冲突聚会）；\n② 情境修正：主动对所处环境情境进行物理或社会修正，改变其情绪诱发强度（如用幽默化解尴尬气氛）；\n③ 注意分配：通过分心或转移注意力来调节情绪唤醒（如看牙医时闭眼听音乐）；\n④ 认知重评（Reappraisal）：在情绪全面萌发前，从积极或理智角度重新解读和构建刺激事件的意义（如将面试紧张重评为展现才华的兴奋机会）。是最健康、最适应的高级调节策略！\n2. 反应关注的情绪调节（情绪已经爆发之后发生）：\n⑤ 表达抑制（Suppression）：克制抑制已经发生的面部表情、躯体动作或言语爆发。缺点：强忍外表虽然平静，但体内交感神经生理唤醒极高，长期会导致身心耗竭损伤健康。",
