      "sourceTag": "【意志行动三大特征必背】",
      "answer": "原笔记第130页核心要点：\n意志是人类特有的高级心理过程，一个真正的意志行动必须同时具备以下三个基本特征：\n1. 具有明确的自觉预定目的：\n• 意志行动是人类主观能动性的最鲜明体现，行动发起前在头脑中已经预先确立了清晰的行动目标与实施蓝图，完全不同于动物盲目受生理本能驱使的无意识反射；\n2. 以克服困难和排除障碍为根本特征（最核心灵魂！）：\n• 克服困难是衡量意志行动的核心试金石。没有任何困难需要克服的随意动作（如口渴顺手端起水杯喝水）不能体现意志的强弱；意志行动必须坚韧克服内部主观障碍（身体疲劳、诱惑惰性、消极情绪）与外部客观环境的重重险阻；\n3. 以一系列随意运动为物质执行基础：\n• 意志行动不是停留在头脑中的纯粹空想，必须通过大脑皮质运动区经锥体束下传支配骨骼肌群做出具体的随意肢体操作，将主观目的转化为客观现实。",
