      "sourceTag": "【精神分析本能动机简答】",
      "answer": "原笔记第52页简答要点：\n弗洛伊德认为，人类一切行为的内在终极动力都源于先天遗传的肉体本能（Instinct）：\n1. 生本能（Eros / 建设性本能）：\n• 核心包括自我保存本能与性本能（力比多 Libido）；\n• 目的在于维持个体生存、寻求快乐体验与物种繁衍，推动人去建立亲密关系、探索知识与创造文明。\n2. 死本能（Thanatos / 破坏性本能）：\n• 指向有机体回到无机无生命状态的原始冲动；\n• 当死本能向外投射时，表现为侵犯、残暴、攻击他人、破坏社会秩序和战争；当死本能向内投射时，表现为自责、自残、自虐乃至自杀行为。\n3. 本能的动态宣泄与升华：\n• 本能冲动如果被社会道德严格压抑，会导致心理疾病；升华是唯一健康、建设性的出路，即将原始本能能量转化为受社会赞许的科学探索、艺术创作或体育竞技活动。",
