      "title": "【高频对比】简述知觉与感觉的区别和联系（简答）",
      "sourceTag": "【感知觉区别联系大题】",
      "answer": "原笔记第73页核心要点：\n1. 区别：\n(1) 反映的内容与深浅不同：感觉是人脑对直接作用于感觉器官的客观事物的【个别属性】（如红、热、甜、响）的反映；知觉是对客观事物的【各个部分和属性的整体综合反映】；\n(2) 生理神经机制不同：感觉是单一感官感受器与特定皮层感觉投射区的活动；知觉是多感觉通道输入与大脑广泛联合区知识经验储备的协同综合神经加工；\n(3) 经验依赖性不同：感觉较少依赖后天经验，更多受生理感受器特性制约；知觉高度依赖个体的知识储备、过去经验与言语概念的中介指导；\n(4) 产生时序不同：感觉是知觉的先导和初级阶段，知觉是感觉的深化与高级整合。\n2. 联系：\n(1) 感觉是知觉的物质基础和信息源泉，没有感知觉器官对物理特征的直接输入，知觉便无从谈起；\n(2) 知觉深化并升华了感觉，人类在现实生活中极少体验到纯粹孤立的感觉，绝大多数都是经过知觉赋予意义后的整体客体映象。",
