      "sourceTag": "【时间知觉影响因素简答】",
      "answer": "原笔记第78-79页简答要点：\n人类对时间跨度长度的主观估计不仅依赖物理时钟，更深受主观心理状态与活动性质制约：\n1. 个人兴趣与情绪状态：\n• 在面对感兴趣、充满愉悦享受的活动时，感觉时间过得飞快（‘欢愉嫌夜短’）；在面对枯燥单调、充满痛苦焦虑的任务时，感觉度日如年（‘寂寞恨更长’）；\n2. 活动内容的性质与复杂程度：\n• 在回忆过去经历的时间时（事后回顾）：经历的事情越丰富多样、新奇复杂，回顾起来觉得时间跨度很长；经历的事情极其单调无聊，事后回顾觉得时间跨度很短；\n• 在正在经历的时间估计中（即时估计）：活动越充实紧张，当下感觉时间越短；活动越单调乏味，当下感觉时间越长；\n3. 意识关注程度与期待：\n• 越是对时间本身进行强烈关注和焦虑等待（如等公交车、等人），觉得时间流逝越缓慢。",
