      "title": "【2017J真题】简述操作性条件作用与经典性条件作用的相同点与不同点（简答）",
      "sourceTag": "【2017J真题·两大条件反射异同】",
      "answer": "原笔记第88页【2017J真题】经典大题：\n1. 相同点：\n(1) 核心本质相同：两者都是有机体在后天个体生活经验中建立起来的条件反射活动，都属于行为习得的形式；\n(2) 基本神经规律相同：都遵循刺激泛化、刺激分化、条件反应消退与自发恢复等基本神经反射动力学规律；\n(3) 强化机制必要性：两者都需要强化的维持，没有强化（伴随无条件刺激或行为满意后果），建立起来的反应都会走向消退。\n2. 不同点：\n(1) 刺激与反应的时序机制不同：\n• 经典条件反射是【S-S 刺激在先】：条件刺激（铃声）呈现在前，诱发被动反应，属于被动反应型条件作用（S-R）；\n• 操作条件反射是【R-S 反应在先】：有机体首先主动做出某种操作行为（按压杠杆），随后外部环境才呈现强化刺激（食物），属于主动操作型条件作用（R-S）；\n(2) 有机体的身心状态不同：经典条件作用中动物是被固定的、被动接受刺激；操作条件作用中动物处于自由探索状态，主动操作改变环境；\n(3) 反映的行为中枢不同：经典条件作用多涉及不随意的自主神经和内脏植物腺体分泌反射；操作条件作用多涉及大脑皮质支配的随意骨骼肌随意运动。",
      "points": [
        "相同点：均为后天习得的条件反射；均遵循泛化、分化、消退与自发恢复规律；均依赖强化维持",
        "不同点1（时序）：经典条件刺激在先被动诱发（S-R） vs 操作条件行为在先主动获得强化（R-S）",
        "不同点2（状态）：被动接受固定环境 vs 主动探索操作环境",
        "不同点3（中枢）：自主神经植物性腺体反射 vs 躯体骨骼肌随意运动（2017J）"
      ]
