      "answer": "原笔记第103-104页【2018L1】【2018L2】【2026选】要点：\n认知心理学关于人类头脑中概念如何表征结构存在两大学派理论：\n1. 经典特征表理论（特质理论，2018L1）：\n• 核心主张：概念是由一组充分且必要的充要本质特征表征构成的；\n• 结构特征：概念的内涵由本质特征决定，属于某概念的所有样例地位完全平等（如‘鸟’的充要特征是羽毛、下蛋、有喙，麻雀和企鹅都是鸟，且地位均等）；概念边界极其清晰分明（要么是，要么不是，全或无）。\n• 局限：无法解释典型性效应（被试判定麻雀是鸟比判定企鹅是鸟反应速度快得多）。\n2. 原型理论（Prototype theory，罗施 Rosch，2018L2）：\n• 核心主张：概念在头脑中不是以死板的充要特征列表存在，而是围绕一个具有最多共同特征的【最佳范例/典型原型（Prototype）】构建的；\n• 结构特征：概念具有【家族相似性】（Family resemblance）；概念各成员地位不平等，存在典型样例（如知更鸟、麻雀）与非典型样例（如鸵鸟、企鹅）；概念之间边界模糊重叠，呈连续过渡谱系。\n• 现实应用：完美解释了模式识别的灵活性和人类日常范畴化推理。",
