      "answer": "原笔记第118页手写口诀【敬礼图册】核心大题：\n人们在听辨口语或阅读书面语篇时，言语理解的深度与速度受四大核心认知因素制约：\n1. 语境线索与情境背景（‘敬’/境）：\n• 言语理解高度依赖上下文语境。语境提供了丰富的背景知识常识，能瞬间消除词义歧义与句法歧义，极大提高解码速度（音位复原效应）；\n2. 心理词库检索与词汇理解（‘礼’/理）：\n• 心理词库（Mental lexicon）中词汇的音形义通达能力。词汇的使用频率、年龄习得早晚直接决定了词汇通达与语义解码的毫秒级反应时；\n3. 已有知识经验与认知图式（‘图’）：\n• 听者/读者头脑中是否具备与当前语篇话题相匹配的认知图式（Schema）。图式为自上而下的预期推理提供脚手架，缺乏图式则即便字字认识依然读不懂深意；\n4. 认知加工策略与心智负荷（‘册’/策）：\n• 个体采用的句法分析解析策略（如最小附着策略、迟延封闭策略）以及工作记忆容量限制。长句嵌套过多超出工作记忆负荷时理解发生崩溃。",
