      "answer": "原笔记第146页核心大题：\n巴甫洛夫通过条件反射实验，依据神经系统兴奋过程与抑制过程的三大基本特性（强度、平衡性、灵活性），确立了四种高级神经活动类型，与古希腊希波克拉底的四种体液气质类型形成了精准的生理心理映射：\n1. 强、不平衡型（不可遏止型） ──▶ 【胆汁质】：\n• 神经特征：兴奋过程显著强于抑制过程，中枢神经爆发力极强但难于自制；\n• 行为表现：精力充沛、热情直爽、行动迅猛、脾气急躁火爆、极易感情用事冲动发怒（典型人物：李逵、张飞）。\n2. 强、平衡、灵活型（活泼型） ──▶ 【多血质】：\n• 神经特征：兴奋与抑制过程都极强且势均力敌，两过程之间的相互转换极其敏捷迅速；\n• 行为表现：活泼好动、敏捷机智、善于交际沟通、适应新环境极快、兴趣广泛；缺点是注意力易转移，情绪不够深沉持久（典型人物：孙悟空、王熙凤）。\n3. 强、平衡、不灵活型（安静型） ──▶ 【粘液质】：\n• 神经特征：兴奋与抑制过程皆强且平衡，但两过程转换缓慢，具有较强惰性；\n• 行为表现：沉着稳健、冷静踏实、坚忍自控、深思熟虑、不苟言笑；缺点是行动相对迟缓，适应新环境较慢，不易向他人吐露心声（典型人物：沙僧）。\n4. 弱型（抑制型） ──▶ 【抑郁质】：\n• 神经特征：兴奋与抑制过程都很微弱，神经细胞容易疲劳产生超限抑制；\n• 行为表现：感受性极高、观察极其细致敏锐、体验深刻持久、内向多思、富于同情心；缺点是行动迟缓脆弱、多愁善感、畏缩孤僻胆小（典型人物：林黛玉）。",
